xml.Script:
        clTop      := 'FFFFFF'; // clWhite;
        clBottom   := 'AFAFAF';
        Colors[ 0] := 'FF0000'; // clRed;
        Colors[ 1] := 'FF6000'; // clOrange;
        Colors[ 2] := 'FFFF00'; // clYellow;
        Colors[ 3] := '008000'; // clGreen;
        Colors[ 4] := '2828FF'; // clLightBlue;
        Colors[ 5] := '0000A0'; // clBlue;
        Colors[ 6] := '800080'; // clViolett;
        Colors[ 7] := 'FF0080'; // clLightViolett;
        Colors[ 8] := '00FF00'; // clLightGreen;
        Colors[ 9] := '800000'; // clBrown;

        Order := 5;

        RequestNumbers('Input prism order', 'Order:', Order);

        Order := Min(Max(Order, 3), 10);

        R := 0.5;

        RCut := R * cos(Pi/Order);

        ColumnsOnSide := 3;
        SideLength := 2 * R * sin(Pi/Order);
        dW := SideLength / ColumnsOnSide * sin(2 * Pi/Order);

        H := Min(SideLength / ColumnsOnSide * 3 / 2, R);

        if Order mod 2 = 1 then begin
            NAxes := Order;
            for i := 0 to NAxes - 1 do begin
                Ax[i] := sin(2*Pi/Order * i);
                Ay[i] := cos(2*Pi/Order * i);
                Az[i] := 0;
            end;
            NSplits := 1;
            Fixed := 0;
        end else begin
            NAxes := Order div 2;
            for i := 0 to NAxes - 1 do begin
                Bx[i] := sin(2*Pi/Order * i);
                By[i] := cos(2*Pi/Order * i);
                Bz[i] := 0;
            end;
            NSplits := 1 * 2;

            WArray[1] := -(RCut - dW);
            Fixed := 1;
        end;
